import pyomo.environ as pyo

DATA = {
    "ingredients": ["sulfate", "ginger"],
    "time_coeff": {"sulfate": 0.5, "ginger": 0.75},
    "min_sulfate": 100.0,
    "min_total": 400.0,
    "sulfate_to_ginger_ratio_limit": 2.0,
    "unit_upper_bound": 1e6,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["ingredients"])

    def x_bounds(m, i):
        return (0, d["unit_upper_bound"])

    model.x = pyo.Var(model.I, within=pyo.NonNegativeReals, bounds=x_bounds)

    def obj_rule(m):
        return sum(d["time_coeff"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def min_sulfate_rule(m):
        return m.x["sulfate"] >= d["min_sulfate"]

    model.min_sulfate = pyo.Constraint(rule=min_sulfate_rule)

    def min_total_rule(m):
        return sum(m.x[i] for i in m.I) >= d["min_total"]

    model.min_total = pyo.Constraint(rule=min_total_rule)

    def ratio_rule(m):
        return m.x["sulfate"] <= d["sulfate_to_ginger_ratio_limit"] * m.x["ginger"]

    model.ratio = pyo.Constraint(rule=ratio_rule)

    return model


